	}

	private static boolean compare(final char[] str1, final char[] str2) {
		for (int i = 0; i < str1.length; ++i) {
			if (str1[i] != str2[i]) {
				return false;
			}
		}
		return true;
	}

	private static char[] rotate(final char[] str, final int startIndex) {
		int index = 0;
		final char[] result = new char[str.length];
		int i = 0;
		for (int i = startIndex; i < str.length; ++i) {
			result[index] = str[i];
			++index;
		}
		for (; i < startIndex;) {
			result[index] = str[i];
			++i;
			++index;
		}
		return result;
	}
