	int count;

	void swap(final int[] A, final int a, final int b) {
		int tmp = A[a];
		A[a] = A[b];
		count += 1;
		A[b] = tmp;
	}

	void selectionSort(final int[] A) {
		for (int i = 0; i < A.length; i++) {
			int minj = i;
			for (int j = i; j < A.length; j++) {
				if (A[j] < A[minj]) {
					minj = j;
				} else {
					minj = minj;
				}
			}
			if (minj != i) {
				swap(A, i, minj);
			}
		}
	}

	void run() {
