	public static int GCD(int x, int y, int z) {
		while (x != y) {
			if (x <= y) {
				y = y - x;
			} else {
				x = x - y;
			}
		}
		for (; x != z;) {
			if (x > z) {
				x = x - z;
			} else {
				z = z - x;
			}
		}
		return z;
	}
}

