	public static String process(final TestCase testCase) {
		final String S = testCase.S;

		int count = 0;

		final char[] chars = S.toCharArray();
        final Deque<Character> stack = new ArrayDeque<>();
		for (char c : chars) {
			if (stack.isEmpty()) {
				stack.push(c);
			} else {
				if (stack.peek().equals(c)) {
					stack.push(c);
				} else {
					stack.pop();
					count = count + (2);
				}
			}
		}

		return String.valueOf(count);
	}

