	int[] parent;

	UnionFind(int n) {
		parent = new int[n];
		Arrays.fill(parent, -1);
	}

	int find(int x) {
		if (parent[x] >= 0) {
			parent[x] = find(parent[x]);
			return parent[x];
		} else {
			return x;
		}
	}

	void unite(int x, int y) {
		int rootX = find(x), rootY = find(y);
		if (rootY == rootX) {
			return;
		}
		if (parent[rootX] > parent[rootY]) {
			int temp = rootX;
			rootX = rootY;
			rootY = temp;
		}
		parent[rootX] = parent[rootX] + (parent[rootY]);
		parent[rootY] = rootX;
	}
}

