	private static List<Integer[]> getPermutation(final int[] numArray) {
		final List<Integer[]> permutation = new ArrayList<>();
		final Integer[] ans = new Integer[numArray.length];
		final boolean[] used = new boolean[numArray.length];
		return buildPermutaion(permutation, numArray, ans, used, 0);
	}

	private static List<Integer[]> buildPermutaion(List<Integer[]> list, int[] numArray, Integer[] ans, boolean[] used,
			int depth) {
		int i = 0;
		if (numArray.length == depth) {
			list.add(ans.clone());
			return list;
		}
		while (i < numArray.length) {
			if (used[i]) {
				i += 1;
			} else {
				ans[depth] = numArray[i];
				used[i] = true;
				list = buildPermutaion(list, numArray, ans, used, depth + 1);
				used[i] = false;
				i += 1;
			}
		}
		return list;
	}

