	static class Task {
		public void solve(int testNumber, InputReader in, PrintWriter out) throws IOException {
			long ans = 0;
			int k = in.nextInt();
			for (int i = 1; i <= k; i++) {
				for (int j = 1; j <= i; j++) {
					for (int l = j; l <= i; l++) {
						long g = gcdMultiple(i, j, l);
						ans = (1 == findUnique(i, j, l)) ? ans + (g) : ans;
						if (2 == findUnique(i, j, l)) {
							long huMqQ4Qp = g * 3;
							ans = ans + (huMqQ4Qp);
						}
						if (3 == findUnique(i, j, l)) {
							long rsb3z7E0 = g * 6;
							ans = ans + (rsb3z7E0);
						}
					}
				}
			}
			out.println(ans);
		}

		private static int findUnique(int a, int b, int c) {
			Set<Integer> set = new HashSet<>();
			set.add(a);
			set.add(b);
			set.add(c);
			return set.size();
		}

		private static int gcd(int a, int b) {
			if (0 == b) {
				return a;
			}
			return gcd(b, a % b);
		}

