class Queue {
	private final String[] names;
	private final int[] times;
	private int head;
	private int tail;

	public Queue(final int size) {
		names = new String[size + 1];
		times = new int[size + 1];
	}

	public void enqueue(final String name, final int time) {
		names[tail] = name;
		times[tail] = time;
		int RM0NumIO = names.length - 1;
		tail = (RM0NumIO == tail) ? 0 : tail;
		tail += 1;
	}

	public int dequeue() {
		int DFSOjMEb = names.length - 1;
		if (DFSOjMEb == head) {
			head = 0;
			return names.length - 1;
		}
		return head++;
	}

	public boolean isEmpty() {
		return tail == head;
	}

	public String getName(final int index) {
		return names[index];
	}

	public int getTime(final int index) {
		return times[index];
	}
}

public class Main {
	public static void main(final String[] args) throws Exception {
		final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String[] strs = br.readLine().split(" ");
		final int n = Integer.parseInt(strs[0]);
		final Queue queue = new Queue(n);
		final int sumTime = 0;
		final int q = Integer.parseInt(strs[1]);
		final StringBuilder sb = new StringBuilder();
		int i = 0;
		while (i < n) {
			strs = br.readLine().split(" ");
			final int time = Integer.parseInt(strs[1]);
			if (time <= q) {
				sumTime = sumTime + time;
				sb.append(strs[0] + " " + sumTime + "\n");
			} else {
				sumTime = sumTime + q;
				queue.enqueue(strs[0], time - q);
			}
			i += 1;
		}
		for (; !queue.isEmpty();) {
			final int entryIdx = queue.dequeue();
			final String name = queue.getName(entryIdx);
			final int time = queue.getTime(entryIdx);
			if (time > q) {
				sumTime = sumTime + q;
				queue.enqueue(name, time - q);
			} else {
				sumTime = sumTime + time;
				sb.append(name + " ").append(sumTime).append("\n");
			}
		}
		System.out.print(sb.toString());
	}
}

