		final Main main = new Main();
		main.solve();
		main.show();
	}

	List<Deque<Integer>> a;
	int ans;
	int turn;
	boolean win;
	static final int A = 0;
	static final int B = 1;
	static final int C = 2;
	static final int N = 3;

	public Main() {
		final Scanner sc = new Scanner(System.in);
		try {
			a = new ArrayList<Deque<Integer>>();
			a.add(read(sc));
			a.add(read(sc));
			a.add(read(sc));
		} finally {
			sc.close();
		}
	}

	private static Deque<Integer> read(final Scanner sc) {
		final String s = sc.next();
		final Deque<Integer> ans = new ArrayDeque<Integer>();
		final int n = s.length();
		int i = 0;
		while (i < n) {
			if ('a' == s.charAt(i)) {
				ans.addLast(A);
			}
			if ('b' == s.charAt(i)) {
				ans.addLast(B);
			}
			if ('c' == s.charAt(i)) {
				ans.addLast(C);
			}
			i++;
		}
		return ans;
	}

	void solve() {
		for (; !win;) {
			play();
		}
	}

	void play() {
		if (0 == a.get(turn).size()) {
			ans = turn;
			win = true;
			return;
		}
		turn = a.get(turn).pollFirst();
	}

	void show() {
		if (A == ans) {
			System.out.println("A");
		}
		if (B == ans) {
			System.out.println("B");
		}
		if (C == ans) {
			System.out.println("C");
		}
	}
}

