class Stack {
	private int top;
    private final int[] a;

	Stack() {
		this.a = new int[200];
		this.top = 0;
	}

	void push(final int x) {
		a[top] = x;
		top += 1;
	}

	int pop() {
		top -= 1;
		return a[top];
	}
}

class Main {
	public static void main(final String[] args) {
		final Stack S = new Stack();
		final Scanner scan = new Scanner(System.in);
		while (scan.hasNext()) {
			final String str = scan.next();
			if (Character.isDigit(str.charAt(0))) {
				S.push(Integer.parseInt(str));
			} else {
				final int b = S.pop();
				final int a = S.pop();
				if (str.charAt(0) == '+') {
					S.push(b + a);
				} else if (str.charAt(0) == '*') {
					S.push(b * a);
				} else if (str.charAt(0) == '-') {
					S.push(b - a);
				}
			}
		}
		System.out.println(S.pop());
	}
}

