class data {
	String name;
	int time;

	data(final String name, final int time) {
		this.time = time;
		this.name = name;
	}
}

class queue {
	ArrayList<data> Q;
	int head, tail;

	queue() {
		head = tail = 0;
		Q = new ArrayList<>();
	}

	void enqueue(final String name, final int time) {
		data process = new data(name, time);
		Q.add(process);
		tail += 1;
	}

	data dequeue() {
		data process = Q.get(head);
		head += 1;
		return process;
	}

	boolean isEmpty() {
		return tail == head;
	}

	void simulate(final int q) {
		ArrayList<data> finish = new ArrayList<>();
		int t;
		int cnt = 0;
		int sum = 0;
		while (!isEmpty()) {
			data temp = dequeue();
			if (temp.time > q) {
				sum = sum + q;
				enqueue(temp.name, temp.time - q);
			} else {
				sum = sum + (temp.time);
				temp.time = sum;
				finish.add(temp);
				cnt += 1;
			}
		}
		for (int i = 0; i < cnt; i++) {
			System.out.println(finish.get(i).name.toString() + " " + finish.get(i).time);
		}
	}
}

